import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxSelect,
  JxButton,
  JxDivider,
  JxBadge,
} from '@jinx-ui/react';

interface SignUpData {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  address: string;
}

interface SignUpWizardProps {
  onSubmit: (data: SignUpData) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
];

export default function SignUpWizard({ onSubmit }: SignUpWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<SignUpData>({
    name: '',
    email: '',
    phone: '',
    country: '',
    city: '',
    address: '',
  });

  const set = (field: keyof SignUpData) => (value: string) =>
    setData((prev) => ({ ...prev, [field]: value }));

  const emailError =
    data.email.length > 0 && !data.email.includes('@')
      ? 'Укажите адрес с символом @'
      : undefined;

  const contactsReady = Boolean(data.name && data.email && !emailError);
  const addressReady = Boolean(data.country && data.city && data.address);
  const canGoNext = step === 0 ? contactsReady : addressReady;

  const countryLabel =
    countries.find((country) => country.value === data.country)?.label ?? '—';

  return (
    <div style={{ display: 'grid', gap: '20px' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={(event) => set('name')(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={(event) => set('email')(event.target.value)}
            errorText={emailError}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            helperText="Необязательно"
            value={data.phone}
            onChange={(event) => set('phone')(event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'grid', gap: '12px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={data.country}
            onValueChange={set('country')}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={(event) => set('city')(event.target.value)}
          />
          <JxTextareaField
            label="Адрес"
            required
            rows={3}
            value={data.address}
            onChange={(event) => set('address')(event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'grid', gap: '10px' }}>
          <JxDivider label="Контакты" />
          <div style={{ display: 'grid', gap: '6px', color: 'var(--jx-text-2)' }}>
            <div>
              Имя: <span style={{ color: 'var(--jx-text)' }}>{data.name}</span>
            </div>
            <div>
              Почта: <span style={{ color: 'var(--jx-text)' }}>{data.email}</span>
            </div>
            <div>
              Телефон:{' '}
              <span style={{ color: 'var(--jx-text)' }}>
                {data.phone ? `+7${data.phone}` : 'не указан'}
              </span>
            </div>
          </div>

          <JxDivider label="Адрес" />
          <div style={{ display: 'grid', gap: '6px', color: 'var(--jx-text-2)' }}>
            <div>
              Страна: <span style={{ color: 'var(--jx-text)' }}>{countryLabel}</span>
            </div>
            <div>
              Город: <span style={{ color: 'var(--jx-text)' }}>{data.city}</span>
            </div>
            <div>
              Адрес: <span style={{ color: 'var(--jx-text)' }}>{data.address}</span>
            </div>
          </div>

          <JxBadge tone="success" dot>
            Данные заполнены
          </JxBadge>
        </div>
      )}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep((current) => current - 1)}
        >
          Назад
        </JxButton>
        {step < 2 ? (
          <JxButton
            variant="primary"
            disabled={!canGoNext}
            onClick={() => setStep((current) => current + 1)}
          >
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={() => onSubmit(data)}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

